package org.apache.commons.math.optimization;

import java.io.*;
import java.math.*;
import java.util.*;
import org.apache.commons.math.ConvergenceException;
import org.apache.commons.math.FunctionEvaluationException;
import org.apache.commons.math.MathRuntimeException;
import org.apache.commons.math.analysis.UnivariateRealFunction;
import org.apache.commons.math.exception.ConvergenceException;
import org.apache.commons.math.exception.FunctionEvaluationException;
import org.apache.commons.math.random.RandomGenerator;
import org.apache.commons.math.util.LocalizedFormats;
import org.apache.commons.math3.analysis.UnivariateRealFunction;
import org.apache.commons.math3.random.RandomGenerator;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.InOrder;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.anyDouble;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.doThrow;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.times;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

public class MultiStartUnivariateRealOptimizer_optimize_TriageGen1Test {

    private UnivariateRealOptimizer mockOptimizer;
    private RandomGenerator mockGenerator;
    private UnivariateRealFunction mockFunction;
    private MultiStartUnivariateRealOptimizer multiStartOptimizer;

    private final int STARTS = 3;
    private final int MAX_ITERATIONS = 100;
    private final int MAX_EVALUATIONS = 100;

    @Before
    public void setUp() {
        mockOptimizer = mock(UnivariateRealOptimizer.class);
        mockGenerator = mock(RandomGenerator.class);
        mockFunction = mock(UnivariateRealFunction.class);

        // We need to use a subclass or a way to set the private fields if they aren't accessible.
        // Since we are testing the provided class logic, we assume the constructor sets these.
        multiStartOptimizer = new MultiStartUnivariateRealOptimizer(mockOptimizer, STARTS, mockGenerator) {
            // Overriding to expose necessary fields if they were protected/package-private
            // In a real scenario, these are set via constructor.
        };

        // Using reflection or assuming the constructor sets these values for the test
        // For the purpose of this test, we assume the internal state is initialized.
        try {
            java.lang.reflect.Field startsField = MultiStartUnivariateRealOptimizer.class.getDeclaredField("starts");
            startsField.setAccessible(true);
            startsField.set(multiStartOptimizer, STARTS);

            java.lang.reflect.Field maxIterField = MultiStartUnivariateRealOptimizer.class.getDeclaredField("maxIterations");
            maxIterField.setAccessible(true);
            maxIterField.set(multiStartOptimizer, MAX_ITERATIONS);

            java.lang.reflect.Field maxEvalField = MultiStartUnivariateRealOptimizer.class.getDeclaredField("maxEvaluations");
            maxEvalField.setAccessible(true);
            maxEvalField.set(multiStartOptimizer, MAX_EVALUATIONS);
        } catch (Exception e) {
            throw new RuntimeException(e);
        }
    }

    @Test
    public void testOptimize_Maximize_Success() throws Exception {
        // Setup: 3 starts. 
        // Start 0: bound1=min, bound2=max
        // Start 1: bound1=min+0.5(max-min), bound2=min+0.2(max-min)
        // Start 2: bound1=min+0.1(max-min), bound2=min+0.8(max-min)

        when(mockGenerator.nextDouble()).thenReturn(0.5, 0.2, 0.1, 0.8);

        // Mock optimizer behavior for 3 calls
        // Call 1 (i=0): returns 1.0, value 10.0
        // Call 2 (i=1): returns 2.0, value 20.0
        // Call 3 (i=2): returns 3.0, value 5.0
        when(mockOptimizer.optimize(eq(mockFunction), eq(GoalType.MAXIMIZE), anyDouble(), anyDouble()))
            .thenReturn(1.0, 2.0, 3.0);

        when(mockOptimizer.getFunctionValue()).thenReturn(10.0, 20.0, 5.0);
        when(mockOptimizer.getIterationCount()).thenReturn(10, 10, 10);
        when(mockOptimizer.getEvaluations()).thenReturn(10, 10, 10);

        double result = multiStartOptimizer.optimize(mockFunction, GoalType.MAXIMIZE, 0.0, 10.0);

        // Best for MAXIMIZE is 2.0 (value 20.0)
        assertEquals(2.0, result, 1e-10);
    }

    @Test
    public void testOptimize_Minimize_Success() throws Exception {
        when(mockGenerator.nextDouble()).thenReturn(0.5, 0.5);

        // Call 1 (i=0): returns 1.0, value 10.0
        // Call 2 (i=1): returns 2.0, value 5.0
        // Call 3 (i=2): returns 3.0, value 15.0
        when(mockOptimizer.optimize(eq(mockFunction), eq(GoalType.MINIMIZE), anyDouble(), anyDouble()))
            .thenReturn(1.0, 2.0, 3.0);

        when(mockOptimizer.getFunctionValue()).thenReturn(10.0, 5.0, 15.0);
        when(mockOptimizer.getIterationCount()).thenReturn(5, 5, 5);
        when(mockOptimizer.getEvaluations()).thenReturn(5, 5, 5);

        double result = multiStartOptimizer.optimize(mockFunction, GoalType.MINIMIZE, 0.0, 10.0);

        // Best for MINIMIZE is 2.0 (value 5.0)
        assertEquals(2.0, result, 1e-10);
    }

    @Test(expected = OptimizationException.class)
    public void testOptimize_AllFailed_ThrowsException() throws Exception {
        when(mockGenerator.nextDouble()).thenReturn(0.5);

        // All calls throw ConvergenceException
        when(mockOptimizer.optimize(any(), any(), anyDouble(), anyDouble()))
            .thenThrow(new ConvergenceException("Fail"));

        multiStartOptimizer.optimize(mockFunction, GoalType.MAXIMIZE, 0.0, 10.0);
    }

    @Test
    public void testOptimize_PartialFailure_HandlesNaN() throws Exception {
        when(mockGenerator.nextDouble()).thenReturn(0.5);

        // i=0: Success (1.0, 10.0)
        // i=1: FunctionEvaluationException (NaN)
        // i=2: Success (3.0, 5.0)
        when(mockOptimizer.optimize(eq(mockFunction), eq(GoalType.MAXIMIZE), anyDouble(), anyDouble()))
            .thenReturn(1.0)
            .thenThrow(new FunctionEvaluationException(mockFunction, 0))
            .thenReturn(3.0);

        when(mockOptimizer.getFunctionValue()).thenReturn(10.0, 0.0, 5.0); // value 0.0 is dummy for NaN case
        when(mockOptimizer.getIterationCount()).thenReturn(1, 1, 1);
        when(mockOptimizer.getEvaluations()).thenReturn(1, 1, 1);

        double result = multiStartOptimizer.optimize(mockFunction, GoalType.MAXIMIZE, 0.0, 10.0);

        // Best is 1.0 (value 10.0)
        assertEquals(1.0, result, 1e-10);

        double[] optima = multiStartOptimizer.getOptima();
        double[] values = multiStartOptimizer.getOptimaValues();

        // Check that NaN was moved to the end
        // Since STARTS=3, and one failed, index 0 and 1 should be valid, index 2 should be NaN
        assertEquals(1.0, optima[0], 1e-10);
        assertEquals(3.0, optima[1], 1e-10);
        assertEquals(Double.NaN, optima[2], 0.0);
    }

    @Test
    public void testOptimize_SortOrder_Complex() throws Exception {
        // Testing the insertion sort logic specifically
        // We want to ensure the sorting logic handles the (goalType == MAXIMIZE) ^ (currY < prevY) correctly
        // Let's simulate values that are not in order.
        // STARTS = 3
        // i=0: x=1, y=10
        // i=1: x=2, y=30 (Greater than 10, should move to front)
        // i=2: x=3, y=20 (Between 10 and 30)

        when(mockGenerator.nextDouble()).thenReturn(0.5);
        when(mockOptimizer.optimize(any(), any(), anyDouble(), anyDouble()))
            .thenReturn(1.0, 2.0, 3.0);
        when(mockOptimizer.getFunctionValue()).thenReturn(10.0, 30.0, 20.0);
        when(mockOptimizer.getIterationCount()).thenReturn(1, 1, 1);
        when(mockOptimizer.getEvaluations()).thenReturn(1, 1, 1);

        double result = multiStartOptimizer.optimize(mockFunction, GoalType.MAXIMIZE, 0.0, 10.0);

        // Expected order: 2.0 (30), 3.0 (20), 1.0 (10)
        assertEquals(2.0, result, 1e-10);
        assertEquals(2.0, multiStartOptimizer.getOptima()[0], 1e-10);
        assertEquals(3.0, multiStartOptimizer.getOptima()[1], 1e-10);
        assertEquals(1.0, multiStartOptimizer.getOptima()[2], 1e-10);
    }

    @Test
    public void testOptimize_UpdateMaxIterationAndEvaluations() throws Exception {
        when(mockGenerator.nextDouble()).thenReturn(0.5);
        when(mockOptimizer.optimize(any(), any(), anyDouble(), anyDouble())).thenReturn(1.0);
        when(mockOptimizer.getFunctionValue()).thenReturn(10.0);
        when(mockOptimizer.getIterationCount()).thenReturn(10);
        when(mockOptimizer.getEvaluations()).thenReturn(10);

        multiStartOptimizer.optimize(mockFunction, GoalType.MAXIMIZE, 0.0, 10.0);

        // Verify that max iterations/evaluations are decremented correctly in the loop
        // First call: MAX_ITERATIONS - 0 = 100
        // Second call: MAX_ITERATIONS - 10 = 90
        verify(mockOptimizer, times(STARTS)).setMaximalIterationCount(anyInt());
        verify(mockOptimizer, times(STARTS)).setMaxEvaluations(anyInt());
    }
}
